  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ApiSnapshotBundlePirResult &&
          runtimeType == other.runtimeType &&
          cachedCount == other.cachedCount &&
          fetchedCount == other.fetchedCount;
}

